<div class="auth-wrap panel"><section class="auth-story"><span class="eyebrow"><?= t('Welcome') ?></span><h2><?= e($s->get('site_name')) ?></h2><p><?= e($s->get('site_tagline')) ?></p><div class="auth-art" aria-hidden="true"><?php $authImage=$a->visuals->image('scene:auth');if($authImage): ?><img class="auth-custom-art" src="<?= e($authImage) ?>" alt="" width="480" height="320"><?php endif ?><div class="orb"></div><div class="orbit-ring"></div><?= icon('sparkles') ?></div><small>EXPLORE. CREATE. BELONG.</small></section><section class="auth-form"><span class="eyebrow"><?= t(!empty($adminLogin)?'Dashboard':'Account') ?></span><h1><?= e($title) ?></h1><p class="auth-subtitle"><?= t($route==='register'?'A few details, and a new beginning.':'Make yourself comfortable. You belong here.') ?></p>
<?= form_start($route) ?><?php if (!empty($adminLogin)) {echo hidden('admin_login','1');} ?>
<?php if ($route==='login'): field('identifier','Username or email','','text',['required'=>'required','autocomplete'=>'username']); field('password','Password','','password',['required'=>'required','autocomplete'=>'current-password']);field('factor_code','Authenticator or recovery code (when enabled)','','text',['maxlength'=>'32','autocomplete'=>'one-time-code']); ?> <div class="row between"><span class="hint"><?= icon('shield') ?><?= t('Your account, protected.') ?></span><?php if ($s->get('smtp_enabled')): ?><a href="<?= e(url('forgot')) ?>"><?= t('Forgot password?') ?></a><?php endif ?></div><?php button('Sign in','full','arrow'); ?>
<?php elseif ($route==='register'): partial('registration_fields'); ?><?php button('Create your account','full','arrow'); ?>
<?php elseif ($route==='forgot'): field('email','Your account email','','email',['required'=>'required','autocomplete'=>'email']); button('Send recovery email','full','arrow'); ?>
<?php else: echo hidden('token',\Chengyu\Core\Input::text($_GET['token']??'',64)); field('password','New password (12+ characters, letters and digits)','','password',['required'=>'required','minlength'=>'12','maxlength'=>'72','autocomplete'=>'new-password']); button('Update password','full','lock'); endif ?></form>
<?php if($route==='login' && empty($adminLogin)){partial('social_buttons');} ?><div class="auth-switch"><?php if ($route==='login' && $s->enabled('registration')): ?><?= t('New around here?') ?> <a href="<?= e(url('register')) ?>"><?= t('Join the community') ?></a><?php else: ?><a href="<?= e(url('login')) ?>"><?= t('Back to sign in') ?></a><?php endif ?></div></section></div>
